arguments.file_text:
#:property AllowUnsafeBlocks=true

Span<nint> signedSpan = stackalloc nint[4];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = i * 10;

Console.WriteLine("Span<nint> via stackalloc:");
foreach (var val in signedSpan)
    Console.WriteLine($"  {val}");

Span<nuint> unsignedSpan = stackalloc nuint[3];
unsignedSpan[0] = 100;
unsignedSpan[1] = 200;
unsignedSpan[2] = 300;

Console.WriteLine("Span<nuint> via stackalloc:");
foreach (var val in unsignedSpan)
    Console.WriteLine($"  {val}");

Console.WriteLine($"\nnint size: {sizeof(nint)} bytes");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");

